"""Fast differential fuzz: reuse the built engine, skip recompilation."""
import importlib.util, json, random, subprocess, sys, time
sys.path.insert(0, '/workspace/tmp')
import reference

spec = importlib.util.spec_from_file_location('submain', '/workspace/submission/main.py')
submain = importlib.util.module_from_spec(spec)
spec.loader.exec_module(submain)

ENGINE = '/workspace/tmp/unit-merge-build/engine'

def run_engine(request):
    try:
        data = submain.transport(request)
    except Exception:
        return {'error': 'invalid'}
    proc = subprocess.run([ENGINE], input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180)
    if proc.returncode != 0:
        raise RuntimeError('engine exit %d %s' % (proc.returncode, proc.stderr.decode()[:500]))
    return json.loads(proc.stdout.decode())

def main():
    seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 50
    sys.path.insert(0, '/workspace/tmp')
    import fuzz
    bad = 0
    for r in range(rounds):
        rng = random.Random(seed0 + r)
        sessions = [fuzz.random_session(rng, legal=(rng.random() < 0.85)) for _ in range(rng.randint(1, 3))]
        request = {'version': 2, 'sessions': sessions}
        try:
            expected = reference.run(request)
        except ValueError:
            expected = {'error': 'invalid'}
        actual = run_engine(request)
        if json.dumps(actual, sort_keys=True) != json.dumps(expected, sort_keys=True):
            bad += 1
            print('seed', seed0 + r, 'MISMATCH')
            open('/workspace/tmp/fail-%d.json' % (seed0 + r), 'w').write(json.dumps(request))
            for i, (a, e) in enumerate(zip(actual.get('sessions', []), expected.get('sessions', []))):
                if json.dumps(a, sort_keys=True) != json.dumps(e, sort_keys=True):
                    print(' session', i)
                    print('  actual  ', json.dumps(a)[:2000])
                    print('  expected', json.dumps(e)[:2000])
                    break
            else:
                print('  actual', json.dumps(actual)[:300], 'expected', json.dumps(expected)[:300])
            if bad >= 3: break
    print('rounds', rounds, 'mismatches', bad)
    return 1 if bad else 0

if __name__ == '__main__':
    raise SystemExit(main())
PYEOF
